<?php
namespace App\Http\Controllers;
use App\Models\Event; use App\Models\EventMealOption; use App\Models\InvitationParty; use App\Models\Rsvp; use App\Models\RsvpPersonResponse; use App\Support\EventPublicationService; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\Rule; use Inertia\Inertia; use Inertia\Response;
class RsvpController extends Controller {
 public function index(Request $request, Event $event): Response { $this->view($request,$event); $search=$request->string('search')->trim()->toString(); $status=$request->string('status')->toString(); $parties=$event->invitationParties()->with(['rsvp.personResponses'])->when($search,fn($q)=>$q->where('name','like',"%{$search}%"))->when(in_array($status,Rsvp::STATUSES,true),fn($q)=>$q->whereHas('rsvp',fn($r)=>$r->where('status',$status)))->orderBy('name')->paginate(25)->withQueryString(); $rsvpSummary=Rsvp::query()->whereHas('party',fn($q)=>$q->where('event_id',$event->id))->selectRaw("SUM(CASE WHEN status <> 'pending' THEN 1 ELSE 0 END) as responded, SUM(CASE WHEN status = 'pending' THEN 1 ELSE 0 END) as pending, SUM(CASE WHEN status = 'attending' THEN 1 ELSE 0 END) as attending_parties, SUM(CASE WHEN status = 'not_attending' THEN 1 ELSE 0 END) as declined_parties")->first(); $peopleSummary=RsvpPersonResponse::query()->whereHas('rsvp.party',fn($q)=>$q->where('event_id',$event->id))->where('is_attending',true)->selectRaw("COUNT(*) as attending_people, SUM(CASE WHEN member_type = 'adult' THEN 1 ELSE 0 END) as adults, SUM(CASE WHEN member_type = 'child' THEN 1 ELSE 0 END) as children")->first(); return Inertia::render('Events/Rsvps/Index',['event'=>$event,'parties'=>$parties->getCollection()->map(fn($party)=>$this->partyForPresentation($party))->values(),'summary'=>['party_count'=>$event->invitationParties()->count(),'responded'=>(int)($rsvpSummary->responded??0),'pending'=>(int)($rsvpSummary->pending??0),'attending_parties'=>(int)($rsvpSummary->attending_parties??0),'declined_parties'=>(int)($rsvpSummary->declined_parties??0),'attending_people'=>(int)($peopleSummary->attending_people??0),'adults'=>(int)($peopleSummary->adults??0),'children'=>(int)($peopleSummary->children??0)],'meals'=>$event->mealOptions()->orderBy('display_order')->get(),'filters'=>['search'=>$search,'status'=>$status],'canManage'=>$request->user()->can('update',$event),'fromSetup'=>$request->boolean('from_setup'),'pagination'=>['current_page'=>$parties->currentPage(),'last_page'=>$parties->lastPage(),'total'=>$parties->total(),'prev_page_url'=>$parties->previousPageUrl(),'next_page_url'=>$parties->nextPageUrl()]]); }
 public function meals(Request $request, Event $event): Response { $this->view($request, $event); return Inertia::render('Events/Meals/Index', ['event' => ['id' => $event->id, 'title' => $event->title], 'meals' => $event->mealOptions()->orderBy('display_order')->get(), 'canManage' => $request->user()->can('update', $event), 'fromSetup' => $request->boolean('from_setup')]); }
 public function show(Request $request, Event $event, InvitationParty $party): Response { $this->view($request,$event); $party=$this->party($event,$party)->load(['rsvp.personResponses.mealOption','members']); return Inertia::render('Events/Rsvps/Show',['event'=>$event,'party'=>$this->partyForPresentation($party)]); }
 public function storeMeal(Request $request, Event $event, EventPublicationService $publications): RedirectResponse { $this->manage($request,$event); $data=$request->validate(['name'=>['required','string','max:255'],'description'=>['nullable','string'],'display_order'=>['nullable','integer','min:0']]); DB::transaction(function() use($event,$data,$request,$publications){$locked=Event::query()->lockForUpdate()->findOrFail($event->id);$locked->mealOptions()->create([...$data,'is_active'=>true,'display_order'=>$data['display_order']??0]);$publications->publishIfActiveLocked($locked,$request->user());}); return $this->afterMealChange($request, $event, 'Meal option added.'); }
 public function updateMeal(Request $request, Event $event, EventMealOption $meal, EventPublicationService $publications): RedirectResponse { $this->manage($request,$event); abort_unless($meal->event_id===$event->id,404); $data=$request->validate(['name'=>['required','string','max:255'],'description'=>['nullable','string'],'display_order'=>['nullable','integer','min:0']]); DB::transaction(function() use($event,$meal,$data,$request,$publications){$locked=Event::query()->lockForUpdate()->findOrFail($event->id);$lockedMeal=EventMealOption::findOrFail($meal->id);abort_unless($lockedMeal->event_id===$locked->id,404);$lockedMeal->update($data);$publications->publishIfActiveLocked($locked,$request->user());}); return $this->afterMealChange($request, $event, 'Meal option updated.'); }
 public function setMealActive(Request $request, Event $event, EventMealOption $meal, EventPublicationService $publications): RedirectResponse { $this->manage($request,$event); abort_unless($meal->event_id===$event->id,404); $data=$request->validate(['is_active'=>['required','boolean']]); DB::transaction(function() use($event,$meal,$data,$request,$publications){$locked=Event::query()->lockForUpdate()->findOrFail($event->id);$lockedMeal=EventMealOption::findOrFail($meal->id);abort_unless($lockedMeal->event_id===$locked->id,404);$lockedMeal->update($data);$publications->publishIfActiveLocked($locked,$request->user());}); return $this->afterMealChange($request, $event, $data['is_active'] ? 'Meal option activated.' : 'Meal option deactivated.'); }
 public function regenerateToken(Request $request, Event $event, InvitationParty $party): RedirectResponse { $this->manage($request,$event); $party=$this->party($event,$party); do { $token=Str::random(64); } while (InvitationParty::where('rsvp_token',$token)->exists()); $party->update(['rsvp_token'=>$token]); return back()->with('success','A new RSVP link was generated.'); }
 private function afterMealChange(Request $request, Event $event, string $message): RedirectResponse { return $request->boolean('from_setup') ? to_route('events.setup', ['event' => $event, 'step' => 3])->with('success', $message) : back()->with('success', $message); } private function view(Request $r,Event $e):void { abort_unless($r->user()->can('view',$e),403); } private function manage(Request $r,Event $e):void { abort_unless($r->user()->can('update',$e),403); } private function party(Event $e,InvitationParty $p):InvitationParty { abort_unless($p->event_id===$e->id,404); return $p; } private function partyForPresentation(InvitationParty $party): array { $rsvp=$party->rsvp; return ['id'=>$party->id,'name'=>$party->name,'maximum_party_size'=>$party->maximum_party_size,'rsvp'=>$rsvp ? ['status'=>$rsvp->status,'guest_message'=>$rsvp->guest_message,'submitted_at'=>$this->dateTime($rsvp->submitted_at),'last_updated_at'=>$rsvp->submitted_at && $rsvp->last_updated_at && $rsvp->submitted_at->isSameSecond($rsvp->last_updated_at) ? null : $this->dateTime($rsvp->last_updated_at),'person_responses'=>$rsvp->personResponses->map(fn($person)=>['id'=>$person->id,'first_name'=>$person->first_name,'last_name'=>$person->last_name,'member_type'=>$person->member_type,'is_original_party_member'=>$person->is_original_party_member,'is_attending'=>$person->is_attending,'dietary_note'=>$person->dietary_note,'meal_option'=>$person->relationLoaded('mealOption') && $person->mealOption ? ['name'=>$person->mealOption->name] : null])->values()] : null]; } private function dateTime(?\DateTimeInterface $dateTime): ?string { return $dateTime ? \Carbon\CarbonImmutable::instance($dateTime)->setTimezone(config('app.timezone'))->format('F j, Y \\a\\t g:i A') : null; }
}
